from eth_abi import encode

DATA_FORMAT_LIST = 1

MODULE_ID_LENGTH = 3
NODE_OPERATOR_ID_LENGTH = 5
VALIDATOR_INDEX_LENGTH = 8
VALIDATOR_PUB_KEY_LENGTH = 48


def hex_str_to_bytes(hex_str: str) -> bytes:
    return bytes.fromhex(hex_str[2:]) if hex_str.startswith("0x") else bytes.fromhex(hex_str)


def encode_data(validators_to_eject):
    """
    Encodes report data for Exit Bus Contract into bytes.

    MSB <------------------------------------------------------- LSB
    |  3 bytes   |  5 bytes   |     8 bytes      |    48 bytes     |
    |  moduleId  |  nodeOpId  |  validatorIndex  | validatorPubkey |
    """
    validators = sorted(validators_to_eject, key=lambda x: (x[0], x[1], x[2]))

    result = b''

    for module_id, op_id, val_index, pub_key in validators:
        result += module_id.to_bytes(MODULE_ID_LENGTH)
        result += op_id.to_bytes(NODE_OPERATOR_ID_LENGTH)
        result += val_index.to_bytes(VALIDATOR_INDEX_LENGTH)

        pubkey_bytes = hex_str_to_bytes(pub_key)

        if len(pubkey_bytes) != VALIDATOR_PUB_KEY_LENGTH:
            raise ValueError(f'Unexpected size of validator pub key. Pub key size: {len(pubkey_bytes)}')

        result += pubkey_bytes

    return result, DATA_FORMAT_LIST


def _encode_data_hash(report_data: tuple):
    # The Accounting Oracle and Ejector Bus has same named method to report data
    # report_function_name = 'emitExitEvents'
    # report_function_abi = next(x for x in veb.abi if x.get('name') == report_function_name)
    # First input is ReportData structure
    # report_data_abi = report_function_abi['inputs'][0]['components']  # type: ignore
    # Transform abi to string
    # report_str_abi = ','.join(map(lambda x: x['type'], report_data_abi))  # type: ignore
    en = encode(['bytes', 'uint256'], report_data)
    h = w3.keccak(en)
    return h

    # Transform str abi to tuple, because ReportData is struct
    # encoded = encode([f'({report_str_abi})'], [report_data])
    # print(encode)

    # report_hash = w3.keccak(text=encoded)
    # return report_hash


def send_report_hash_to_veb(data: list[tuple[int, int, int, str]], force):
    tx_data = encode_data(data)
    # print(f'Tx data: {tx_data}')
    tx_hash = _encode_data_hash(tx_data)
    print(f'Report hash: {tx_hash.hex()}')
    submit_hash = veb.functions.submitExitRequestsHash(tx_hash)
    tx_hash = w3.tx.check_and_send_transaction(submit_hash, ACCOUNT, force)
    print('Hash submitted')
    # print(tx_hash)


def submit_report_data_to_veb(data: list, force: bool):
    tx_data = encode_data(data)
    # print(f'Tx data: {tx_data}')
    tx = veb.functions.submitExitRequestsData(tx_data)
    tx_hash = w3.tx.check_and_send_transaction(tx, ACCOUNT, force)
    print('Data unpacked')


def get_validators_from_kapi(from_i: int, count: int):
    cl_vals = requests.get('http://0.0.0.0:33546/eth/v1/beacon/states/head/validators')
    assert cl_vals.status_code == 200
    cl_vals = cl_vals.json()['data']

    res = requests.get('http://0.0.0.0:33571/v1/keys')
    assert res.status_code == 200

    keys = res.json()['data']
    vals = []

    for i in range(from_i, count + from_i):
        for v in cl_vals:
            v_index = -1

            if v['validator']['pubkey'] == keys[i]['key']:
                v_index = v['index']
                break

        assert v_index != -1

        vals.append((1, keys[i]['operatorIndex'], int(v_index), keys[i]['key']))

    validators = sorted(vals, key=lambda x: (x[0], x[1], x[2]))

    return validators

def shuffle(l: list):
    import random
    random.shuffle(l)

